'use strict';
const workflow={recipes:[],customers:[],analysis:null,tab:'checks',script:null,selectedCustomer:null};
const labelRecipe=p=>`${p.gpu} · ${p.fabric==='spectrum-x'?'Spectrum-X / RoCE':'InfiniBand'}`;
const badge=s=>`<span class="status ${s==='pass'?'pass':s==='fail'?'fail':'unknown'}">${esc({pass:'Observed match',fail:'Mismatch',unknown:'Missing evidence',review:'Review required'}[s]||s)}</span>`;
function selectItems(id,items,placeholder){const el=$(id),old=el.value;el.innerHTML=(placeholder?`<option value="">${esc(placeholder)}</option>`:'')+items.map(i=>`<option value="${esc(i.id)}">${esc(i.label||i.name)}</option>`).join('');if(items.some(i=>i.id===old))el.value=old;}
async function loadWorkflows(view){try{if(!workflow.recipes.length){workflow.recipes=(await api('/api/recipes')).items;for(const id of ['analysis-recipe','script-recipe','engagement-recipe'])selectItems(id,workflow.recipes.map(p=>({id:p.id,label:labelRecipe(p)})));updateRecipe();}
if(view==='engagements'||view==='troubleshoot'){const b=await api('/api/customers');workflow.customers=b.items;for(const id of ['analysis-customer','engagement-customer'])selectItems(id,b.items,id==='analysis-customer'?'Unassigned analysis':'Select customer');updateAnalysisEngagement();if(view==='engagements')renderBoard(b);}}catch(e){setError($(view==='engagements'?'board-error':view==='scripts'?'script-error':'analysis-error'),e.message);}}
function updateAnalysisEngagement(){const c=workflow.customers.find(c=>c.id===$('analysis-customer').value);selectItems('analysis-engagement',(c?.engagements||[]).map(e=>({id:e.id,label:`${e.title} · ${e.status}`})),'No engagement — upload now');$('analysis-engagement').required=false;$('analysis-engagement').disabled=!c||!c.engagements.length;syncAnalysisRecipe();}
function syncAnalysisRecipe(){const c=workflow.customers.find(c=>c.id===$('analysis-customer').value),e=c?.engagements.find(e=>e.id===$('analysis-engagement').value);$('analysis-recipe').disabled=!!e;if(e){$('analysis-recipe').value=e.recipe_id;if(!$('analysis-cluster').value&&c.clusters.length===1)$('analysis-cluster').value=c.clusters[0];}}
function updateRecipe(){const p=workflow.recipes.find(p=>p.id===$('script-recipe').value);if(!p)return;$('script-gpus').value=p.gpus_per_node;$('recipe-note').textContent=`Profile ${p.version}. ${p.notes.join(' ')}`;updateScriptTuningControls();}
function analysisTab(tab){workflow.tab=tab;if(state.view==='troubleshoot')document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('[data-analysis-tab]').forEach(b=>{b.classList.toggle('primary',b.dataset.analysisTab===tab);b.classList.toggle('secondary',b.dataset.analysisTab!==tab);b.setAttribute('aria-pressed',String(b.dataset.analysisTab===tab));});renderAnalysis();}
function observedCheck(value){if(value==null||Array.isArray(value)&&!value.length)return 'Not present in upload';if(Array.isArray(value)&&value.length>100)return `${JSON.stringify(value.slice(0,100))} — showing first 100 of ${num(value.length)} observations; all retained in saved report.`;return typeof value==='object'?JSON.stringify(value):value;}
const XID_AREA={application:'Application',hardware:'Hardware / node',ecc_memory:'GPU memory (ECC)',driver_firmware:'Driver / firmware',follow_on:'Follow-on (see the earlier Xid)',unclassified:'Not in this tool\'s table'};
const HOST_ROLE={reporter:'Logged the line',named:'Named by scheduler',peer_address:'Peer address'};
function crashDetail(g){const xids=g.xids||[],hosts=g.hosts||[];const x=xids.length?`<div class="table-wrap"><table><thead><tr><th>Xid</th><th>Meaning</th><th>Likely area</th><th>Count</th><th>GPU (PCI)</th><th>First seen</th></tr></thead><tbody>${xids.map(r=>`<tr><td>${r.code}</td><td class="wrap-cell">${esc(r.name||'Unrecognized Xid')}<br><small>${esc(r.action)}</small></td><td>${esc(XID_AREA[r.domain]||r.domain)}</td><td>${num(r.count)}</td><td class="xid-device">${r.devices.length?r.devices.map(d=>esc(d.device)).join(', '):'Not stated'}</td><td class="wrap-cell">${esc(r.first_seen.file)} : line ${r.first_seen.line}</td></tr>`).join('')}</tbody></table></div><small>Meanings follow NVIDIA's Xid catalog. The area is a likely cause, not a diagnosis.</small>`:'';const h=hosts.length?`<p class="form-note">Hosts in these lines: ${hosts.map(r=>`${esc(r.host)} (${esc(HOST_ROLE[r.role]||r.role)}, ${num(r.count)})`).join('; ')}</p>`:'';return x+h;}
function hostAttribution(a){const h=a.host_attribution;if(!h||!h.items?.length)return '';return `<div class="finding"><h3>Hosts named in crash evidence</h3><p class="form-note">${esc(h.note)}</p><div class="table-wrap"><table><thead><tr><th>Host</th><th>Role</th><th>Lines</th><th>Signatures</th><th>First seen</th></tr></thead><tbody>${h.items.map(r=>`<tr><td class="wrap-cell">${esc(r.host)}</td><td>${esc(HOST_ROLE[r.role]||r.role)}</td><td>${num(r.count)}</td><td class="wrap-cell">${Object.entries(r.signatures).map(([k,v])=>`${esc(k)} ${num(v)}`).join(', ')}</td><td class="wrap-cell">${esc(r.first_seen.file)} : line ${r.first_seen.line}</td></tr>`).join('')}</tbody></table></div>${h.truncated?`<small>Showing ${num(h.items.length)} of ${num(h.total_hosts)} hosts; the list is bounded.</small>`:''}</div>`;}
function renderAnalysis(){const a=workflow.analysis;if(!a)return;const heading=`<div class="section-header"><div><div class="eyebrow">${esc(labelRecipe(a.recipe))} · ${esc(a.policy_version)}</div><h2>${a.verdict==='fail'?'Evidence needs attention':'Review configuration evidence'}</h2><p>Saved ${esc(new Date(a.created_at).toLocaleString())} · ${num(a.ingestion?.member_count??a.files.length)} files</p>${a.id?`<p><a class="secondary small" href="?analysis=${encodeURIComponent(a.id)}">Open saved report ↗</a></p><div class="performance-reassess"><button class="secondary small" type="button" data-performance-reassess="${esc(a.id)}">Reassess against latest references</button><span class="performance-reassess-message" data-performance-reassess-message role="status"></span></div>`:''}</div>${badge(a.verdict==='fail'?'fail':'review')}</div>`;
let body='';if(workflow.tab==='checks')body=`<div class="table-wrap"><table><thead><tr><th>Check</th><th>Expected / investigation</th><th>Observed</th><th>Assessment</th></tr></thead><tbody>${a.checks.map(c=>`<tr><td>${esc(c.title)}</td><td>${esc(c.expected)}</td><td class="wrap-cell">${esc(observedCheck(c.observed))}</td><td>${badge(c.status)}</td></tr>`).join('')}</tbody></table></div>`;
if(workflow.tab==='crashes')body=a.crashes.length?hostAttribution(a)+a.crashes.map(g=>`<div class="finding"><div class="section-header"><h3>${esc(g.title)}</h3><span class="pill">${g.count} matches</span></div><p>${esc(g.next_action)}</p><small>${esc(g.confidence)}</small>${crashDetail(g)}${g.evidence.map(e=>`<details><summary>${esc(e.file)} : line ${e.line}</summary><pre class="code-panel">${esc(e.excerpt)}</pre></details>`).join('')}</div>`).join(''):'<div class="empty-cell"><strong>No recognized crash signatures.</strong>Review configuration and completeness checks; this does not prove the run was healthy.</div>';
if(workflow.tab==='follow')body=`${renderInvestigation(a.investigation)}${a.follow_up_tests.length>100?`<p class="form-note">Showing the first 100 of ${num(a.follow_up_tests.length)} follow-up tests, ordered by priority. The complete list is retained in the saved report.</p>`:''}<div class="follow-grid">${a.follow_up_tests.slice(0,100).map(t=>`<article class="finding"><span class="eyebrow">PRIORITY ${t.priority}</span><h3>${esc(t.title)}</h3><p>${esc(t.reason)}</p><pre class="code-panel">${esc(t.command)}</pre><p><strong>Look for: </strong>${esc(t.success)}</p></article>`).join('')}</div><p><button class="primary" onclick="openRecipeScript()">Generate a follow-up NCCL script →</button></p>`;
if(workflow.tab==='comparison'){const comparisons=prioritizedComparisons(a).filter(c=>hasMeasurements(c)||c.run.status==='failed');body=`<p class="form-note">Showing ${num(Math.min(100,comparisons.length))} of ${num(comparisons.length)} measured or failed logs. Measured training logs appear first. All artifacts remain available in the validation explorer.</p>`+comparisons.slice(0,100).map(c=>c.run?.workload==='NCCL'?renderNcclComparison(c,c.filename):renderComparison(c,c.filename)+performanceAssessment(performanceOf(c))).join('')+referenceReviewForm(a);}
$('analysis-results').innerHTML=`<div class="card">${heading}${performanceOverview(a)}${ingestionSummary(a)}${body}<div class="info-box">${a.limitations.map(esc).join('<br>')}</div><p class="form-note">Sources: ${a.recipe.sources.map(s=>`<a target="_blank" rel="noreferrer" href="${esc(s)}">${esc(new URL(s).hostname)}</a>`).join(' · ')}</p></div>`;updateReassessControls();}
$('analysis-form').addEventListener('submit',async e=>{e.preventDefault();setError($('analysis-error'),null);const b=$('analysis-submit');const file=$('analysis-file').files[0];const contextJson=$('analysis-context-json').value.trim();if(contextJson){try{const context=JSON.parse(contextJson);if(!context||typeof context!=='object'||Array.isArray(context))throw new Error('Enter a JSON object.');}catch(error){setError($('analysis-error'),`Benchmark context must be a valid JSON object: ${error.message}`);$('analysis-context-json').focus();return;}}if(file.size>1000000000){setError($('analysis-error'),'Upload limit is 1 GB per file. Choose a smaller archive.');return;}b.disabled=true;b.textContent='Uploading…';try{const f=new FormData();f.append('file',$('analysis-file').files[0]);if(contextJson)f.append('context_json',contextJson);for(const [k,id]of Object.entries({recipe_id:'analysis-recipe',customer_id:'analysis-customer',engagement_id:'analysis-engagement',cluster:'analysis-cluster',reference_cluster:'analysis-reference',tolerance_pct:'analysis-tolerance',nodes:'analysis-nodes',gpus:'analysis-gpus',hardware:'analysis-hardware',transport:'analysis-transport',nccl_version:'analysis-nccl'})){if($(id).value.trim())f.append(k,$(id).value.trim());}workflow.analysis=await uploadEvidence(f);initialize();analysisTab(workflow.tab);$('analysis-results').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){setError($('analysis-error'),e.message);}finally{b.disabled=false;b.textContent='Ingest & analyze →';}});
$('analysis-customer').addEventListener('change',updateAnalysisEngagement);$('analysis-engagement').addEventListener('change',syncAnalysisRecipe);
document.querySelectorAll('[data-analysis-tab]').forEach(b=>b.addEventListener('click',()=>analysisTab(b.dataset.analysisTab)));
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>analysisTab(b.dataset.tab)));
$('analysis-results').addEventListener('click',e=>{const b=e.target.closest('[data-baseline]');if(b)showDetail(b.dataset.baseline);});
$('script-recipe').addEventListener('change',updateRecipe);
$('script-form').addEventListener('submit',async e=>{e.preventDefault();setError($('script-error'),null);const req={recipe_id:$('script-recipe').value,nodes:Number($('script-nodes').value),gpus_per_node:Number($('script-gpus').value),collective:$('script-collective').value,partition:$('script-partition').value,image:$('script-image').value,binary_dir:$('script-bin').value,hca:$('script-hca').value,interface:$('script-interface').value,min_bytes:Number($('script-min').value),max_bytes:Number($('script-max').value),iterations:Number($('script-iterations').value),warmup:Number($('script-warmup').value),tuning_preset:$('script-tuning-preset').value,...($('script-registration').value!==''?{registration:Number($('script-registration').value)}:{}),repeats:Number($('script-repeats').value),split:$('script-split').checked};try{workflow.script=await api('/api/nccl-script',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(req)});$('script-code').textContent=workflow.script.script;$('script-warnings').textContent=workflow.script.warnings.join(' ');$('script-output').hidden=false;}catch(e){setError($('script-error'),e.message);}});
$('script-download').addEventListener('click',()=>{if(!workflow.script)return;const url=URL.createObjectURL(new Blob([workflow.script.script],{type:'text/x-shellscript'})),a=document.createElement('a');a.href=url;a.download=workflow.script.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
async function boardWrite(path,body,method='POST'){setError($('board-error'),null);try{const r=await api(path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await loadWorkflows('engagements');return r;}catch(e){setError($('board-error'),e.message);return null;}}
$('customer-form').addEventListener('submit',async e=>{e.preventDefault();if(await boardWrite('/api/customers',{name:$('customer-name').value,clusters:$('customer-clusters').value.split(',').map(s=>s.trim()).filter(Boolean)}))e.target.reset();});
$('engagement-form').addEventListener('submit',async e=>{e.preventDefault();if(await boardWrite('/api/engagements',{customer_id:$('engagement-customer').value,title:$('engagement-title').value,status:$('engagement-status').value,recipe_id:$('engagement-recipe').value,notes:$('engagement-notes').value})){ $('engagement-title').value='';$('engagement-notes').value='';}});
$('board-refresh').addEventListener('click',()=>loadWorkflows('engagements'));
function renderBoard(b){const totals=b.items.reduce((a,c)=>{for(const k of ['validations','active_engagements','planned_engagements','valid_logs'])a[k]=(a[k]||0)+c[k];return a;},{});$('board-content').innerHTML=`<div class="stats-grid">${[['validations','Validations'],['active_engagements','Active engagements'],['planned_engagements','Planned engagements'],['valid_logs','Valid logs']].map(([k,l])=>`<div class="stat"><span>${l}</span><strong>${num(totals[k]||0)}</strong><small>Across registered customers</small></div>`).join('')}</div><div class="results-panel table-wrap"><table><thead><tr><th>Customer</th><th>Validations</th><th>Active / planned</th><th>Valid logs</th><th>Final numbers</th><th>Exemplar results</th></tr></thead><tbody>${b.items.length?b.items.map(c=>`<tr><td><button class="secondary" data-customer="${esc(c.id)}">${esc(c.name)} ↗</button><div class="form-note">${esc(c.clusters.join(', ')||'No historical cluster mapping')}</div></td><td>${num(c.validations)}<small class="block">${num(c.records)} evidence records</small></td><td>${c.active_engagements} / ${c.planned_engagements}</td><td>${num(c.valid_logs)}</td><td>${num(c.final_results)}</td><td>${num(c.exemplar_results)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-cell">Register a customer and map their clusters to start tracking history.</td></tr>'}</tbody></table></div><p class="form-note">${esc(b.count_policy)}</p>`;if(workflow.selectedCustomer)renderCustomer(workflow.selectedCustomer);}
function renderCustomer(id){workflow.selectedCustomer=id;const c=workflow.customers.find(c=>c.id===id);if(!c)return;const options='<option value="">No engagement — customer evidence</option>'+c.engagements.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('');$('customer-detail').innerHTML=`<article class="card customer-card"><div class="eyebrow">CUSTOMER SUMMARY</div><h2>${esc(c.name)}</h2><form id="customer-edit-form"><div class="form-grid"><label>Name<input name="name" value="${esc(c.name)}" required></label><label>Mapped clusters<input name="clusters" value="${esc(c.clusters.join(', '))}"></label></div><p><button class="secondary small">Save customer mapping</button></p></form><h3>Engagements</h3>${c.engagements.length?c.engagements.map(e=>`<div class="engagement-row"><div><strong>${esc(e.title)}</strong><p>${esc(e.recipe_id)} · ${esc(e.notes||'No notes')}</p></div><label>State<select data-engagement-state="${esc(e.id)}">${['planned','active','blocked','completed'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></label><button class="secondary small" data-upload-engagement="${esc(e.id)}">Upload logs →</button></div>`).join(''):'<p>No engagements yet. Create one above.</p>'}<h3>Best measured performance by configuration</h3><p class="form-note">Correctness-clean NCCL evidence. Peak bus bandwidth is a measured point; compare rows only with matching configuration and split mask.</p><div class="table-wrap"><table><thead><tr><th>GPU / fabric</th><th>Scale / collective</th><th>NCCL / split</th><th>Best measured point</th></tr></thead><tbody>${c.best_performance.length?c.best_performance.map(r=>`<tr><td>${esc(r.hardware||'Unknown')}<small class="block">${esc(r.transport||'Unknown')}</small></td><td>${num(r.nodes)} nodes / ${num(r.gpus)} GPUs<small class="block">${esc(r.collective||'Unknown')}</small></td><td>${esc(r.nccl_version||'Unknown')}<small class="block">mask ${esc(r.split_mask??'unspecified')}</small></td><td>${num(r.peak_bus_bw_gbps,2)} GB/s<small class="block">${r.point?`${bytes(r.point.message_bytes)} · ${esc(r.point.datatype)} · ${esc(r.point.placement)}`:''}</small>${r.id?`<button class="secondary small" data-evidence-run="${esc(r.id)}">Inspect source ↗</button>`:''}</td></tr>`).join(''):'<tr><td colspan="4">No valid measured results yet.</td></tr>'}</tbody></table></div>${trainingPerformance(c)}<h3>Saved investigations</h3>${c.analyses.length?c.analyses.map(a=>`<p><button class="secondary small" data-analysis-id="${esc(a.id)}">${esc(a.filename)} ↗</button> <span class="muted">${esc(a.recipe_id)} · ${esc(new Date(a.created_at).toLocaleDateString())}</span></p>`).join(''):'<p>No investigations uploaded.</p>'}<h3>Final numbers & Exemplar results</h3><p class="form-note">Attach a measured run from the explorer by its run ID. Final / Exemplar labels require complete source-backed training or correctness-clean NCCL evidence and record your explicit designation.</p><form id="evidence-form"><div class="form-grid"><label>Run ID<input name="run_id" required></label><label>Engagement<select name="engagement_id">${options}</select></label><label class="toggle-label"><input name="final" type="checkbox"> Final number</label><label class="toggle-label"><input name="exemplar" type="checkbox"> Exemplar result</label></div><p><button class="secondary">Save result designation</button></p></form><p class="form-note">Showing ${num(Math.min(100,c.evidence.length))} of ${num(c.evidence_total??c.evidence.length)} linked evidence records. All ingested logs remain available in the validation explorer.</p><div class="table-wrap"><table><thead><tr><th>Evidence</th><th>Performance</th><th>Final</th><th>Exemplar</th></tr></thead><tbody>${c.evidence.slice(0,100).map(r=>`<tr><td><button class="secondary small" data-evidence-run="${esc(r.run_id)}">${esc(r.title)}</button><small class="block">${esc(r.run_id)} · ${esc(r.status)}</small></td><td>${measuredPerformance(r)}<small class="block">${esc(r.workload||'NCCL')} · ${esc(r.hardware)} · ${num(r.gpus)} GPUs${r.collective?` · ${esc(r.collective)}`:''}</small></td><td>${r.final?'Yes':'—'}</td><td>${r.exemplar?'Yes':'—'}</td></tr>`).join('')||'<tr><td colspan="4">No linked evidence yet.</td></tr>'}</tbody></table></div></article>`;
$('customer-edit-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await boardWrite(`/api/customers/${id}`,{name:f.get('name'),clusters:f.get('clusters').split(',').map(s=>s.trim()).filter(Boolean)},'PUT');});
$('evidence-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await boardWrite(`/api/customers/${id}/evidence`,{run_id:f.get('run_id'),engagement_id:f.get('engagement_id'),final:f.has('final'),exemplar:f.has('exemplar')});});
}
$('board-content').addEventListener('click',e=>{const b=e.target.closest('[data-customer]');if(b){renderCustomer(b.dataset.customer);$('customer-detail').scrollIntoView({behavior:'smooth'});}});
$('customer-detail').addEventListener('change',async e=>{const id=e.target.dataset.engagementState;if(!id)return;const c=workflow.customers.find(c=>c.id===workflow.selectedCustomer),item=c.engagements.find(x=>x.id===id);await boardWrite(`/api/engagements/${id}`,{...item,status:e.target.value},'PUT');});
$('customer-detail').addEventListener('click',async e=>{const run=e.target.closest('[data-evidence-run]');if(run){showDetail(run.dataset.evidenceRun);return;}const a=e.target.closest('[data-analysis-id]');if(a){try{workflow.analysis=await api(`/api/analyses/${a.dataset.analysisId}`);showView('troubleshoot');analysisTab('checks');}catch(err){setError($('board-error'),err.message);}return;}const b=e.target.closest('[data-upload-engagement]');if(b){const c=workflow.customers.find(c=>c.id===workflow.selectedCustomer);showView('troubleshoot');await loadWorkflows('troubleshoot');$('analysis-customer').value=c.id;updateAnalysisEngagement();$('analysis-engagement').value=b.dataset.uploadEngagement;syncAnalysisRecipe();}});

$('analysis-file').addEventListener('change',()=>{$('analysis-file-label').textContent=$('analysis-file').files[0]?.name||'Choose logs or a log bundle';});
async function openRecipeScript(){showView('scripts');await loadWorkflows('scripts');const a=workflow.analysis;$('script-recipe').value=a?.recipe.id||$('analysis-recipe').value;updateRecipe();const r=a?.comparisons.find(c=>c.run?.nodes&&c.run?.gpus)?.run;if(r){$('script-nodes').value=r.nodes;const g=r.gpus/r.nodes;if([1,2,4,8].includes(g))$('script-gpus').value=g;}if(r&&['all_reduce','all_gather','reduce_scatter','alltoall','sendrecv'].includes(r.collective))$('script-collective').value=r.collective;updateScriptTuningControls();}

function hasMeasurements(c){const m=c.measurement||c.run;return !!(m.measured_points||c.run?.metrics?.length||m.peak_bus_bw_gbps!=null||m.tflops_gpu!=null||m.mean_step_time_ms!=null||m.iterations!=null);}
function prioritizedComparisons(a){const rank=c=>hasMeasurements(c)?((c.measurement||c.run).workload==='NCCL'?1:0):c.run?.status==='failed'?2:3;return [...a.comparisons].sort((a,b)=>rank(a)-rank(b));}
function ingestionSummary(a){if(!a.ingestion)return '';const b=a.baseline_attainment,i=a.ingestion,ordered=prioritizedComparisons(a),measured=ordered.filter(hasMeasurements).length;return `<div class="info-box"><strong>Ingested into ${esc(a.cluster)}</strong> · ${i.member_count} log files · ${bytes(i.original_bytes)} original evidence retained<br>SHA-256: <span class="receipt-hash">${esc(i.original_sha256)}</span><p>Reference selection: ${esc(a.reference_cluster||'All compatible qualified clusters')}. ${esc(i.reference_policy)}</p></div><div class="stats-grid ingestion-stats">${[['Measured runs',i.measured_runs],['Baseline met',b.runs_met],['Below baseline / failed',b.runs_below_or_failed],['Needs reference evidence',b.runs_unscored]].map(([l,v])=>`<div class="stat"><span>${l}</span><strong>${num(v)}</strong></div>`).join('')}</div><p class="form-note">Showing ${num(Math.min(100,ordered.length))} of ${num(ordered.length)} ingested log artifacts (${num(measured)} with measured results). Measured training logs appear first, followed by measured NCCL runs and diagnostic evidence. All ingested artifacts remain searchable in the validation explorer.</p><div class="table-wrap"><table><thead><tr><th>Ingested log</th><th>Workload / scale</th><th>Measured numbers</th><th>Baseline</th></tr></thead><tbody>${ordered.slice(0,100).map(c=>{const m=c.measurement||c.run;return `<tr><td><button class="secondary small" data-baseline="${esc(c.run_id)}">${esc(c.filename)} ↗</button></td><td>${esc(m.workload)}${m.collective?` / ${esc(m.collective)}`:''}<small class="block">${num(m.nodes)} nodes / ${num(m.gpus)} GPUs</small></td><td>${m.peak_bus_bw_gbps!=null?`${num(m.peak_bus_bw_gbps,2)} GB/s peak bus`:m.tflops_gpu!=null?`${num(m.tflops_gpu,2)} TFLOP/s/GPU · mean`:'No bandwidth / throughput summary'}${m.mean_step_time_ms!=null?`<small class="block">${num(m.mean_step_time_ms,2)} ms / step</small>`:''}<small class="block">${status(m.status,m.workload)}</small></td><td>${performanceOf(c)?performanceCompact(performanceOf(c)):hasMeasurements(c)?status(c.verdict):'Diagnostic evidence'}</td></tr>`;}).join('')}</tbody></table></div>`;}
function referenceReviewForm(a){const candidates=a.comparisons.filter(c=>c.run.workload==='NCCL'&&c.run.metrics.length);if(!a.ingestion||!candidates.length)return '';return `<form id="reference-review-form" class="finding"><h3>Grow the reviewed reference library</h3><p>Uploads remain observations until an engineer reviews a complete, correctness-clean run with exact configuration. This action affects future comparisons; this saved report retains its original assessment.</p><div class="form-grid"><label>Run<select name="run_id">${candidates.map(c=>`<option value="${esc(c.run_id)}">${esc(c.filename)}</option>`).join('')}</select></label><label>Reviewing engineer<input name="reviewer" maxlength="120" required></label><label>Review rationale<input name="reason" minlength="10" maxlength="2000" required></label><label class="toggle-label"><input name="active" type="checkbox" checked> Enable as reusable reference</label></div><p><button class="secondary">Save reference review</button></p><div id="reference-review-message" role="status"></div></form>`;}
$('analysis-results').addEventListener('submit',async e=>{if(e.target.id!=='reference-review-form')return;e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('button');button.disabled=true;try{await api('/api/reference-reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({run_id:f.get('run_id'),reviewer:f.get('reviewer'),reason:f.get('reason'),active:f.has('active')})});$('reference-review-message').textContent='Reference review saved. Future compatible uploads will use the current review state.';}catch(err){$('reference-review-message').textContent=err.message;}finally{button.disabled=false;}});
function renderUploadLake(data){const host=$('upload-lake-inventory');if(!host)return;loadReceivedEvidence(host);loadPerformanceLibrary();loadNcclReferenceLibrary();loadConfluenceSources();const s=data.summary;host.innerHTML=`<div class="section-header"><div><h2>Uploaded cluster evidence</h2><p>${num(s.batches)} upload batches · ${bytes(s.original_bytes)} originals · ${num(s.measured_runs)} measured runs · ${num(s.reviewed_references)} reviewed references</p></div></div><div class="results-panel table-wrap"><table><thead><tr><th>Cluster</th><th>Original source</th><th>Evidence</th><th>Ingested</th></tr></thead><tbody>${data.items.map(i=>`<tr><td>${esc(i.cluster)}</td><td>${esc(i.filename)}<small class="block receipt-hash">SHA-256 ${esc(i.sha256)}</small></td><td>${i.member_count} logs / ${i.measured_runs} measured runs<small class="block">${bytes(i.size_bytes)}</small></td><td>${esc(new Date(i.created_at).toLocaleString())}</td></tr>`).join('')||'<tr><td colspan="4">Upload logs with a cluster name to populate this inventory.</td></tr>'}</tbody></table></div>`;}

async function moveArchiveToIngestion(file){showView('troubleshoot');await loadWorkflows('troubleshoot');const transfer=new DataTransfer();transfer.items.add(file);$('analysis-file').files=transfer.files;$('analysis-file').dispatchEvent(new Event('change'));for(const [source,target]of Object.entries({'upload-cluster':'analysis-cluster','upload-nodes':'analysis-nodes','upload-gpus':'analysis-gpus','upload-hardware':'analysis-hardware','upload-transport':'analysis-transport','upload-nccl':'analysis-nccl','upload-tolerance':'analysis-tolerance'})){if($(source).value.trim())$(target).value=$(source).value.trim();}$('analysis-cluster').focus();}

let activeEvidenceUpload=null;
function uploadEvidence(form){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();activeEvidenceUpload=xhr;const panel=$('upload-progress-panel'),bar=$('upload-progress'),label=$('upload-progress-label'),stage=$('upload-progress-stage'),cancel=$('upload-cancel');panel.hidden=false;bar.value=0;label.textContent='Uploading… 0%';stage.textContent='Sending your log archive to Validation Hub.';cancel.disabled=false;cancel.hidden=false;const started=performance.now();
function finish(){activeEvidenceUpload=null;cancel.disabled=true;}
xhr.open('POST','/api/analyze');xhr.timeout=0;
xhr.upload.onprogress=e=>{if(!e.lengthComputable){bar.removeAttribute('value');label.textContent='Uploading…';return;}const percent=Math.min(100,e.loaded/e.total*100);bar.value=percent;label.textContent=`Uploading… ${Math.floor(percent)}%`;const elapsed=Math.max(.1,(performance.now()-started)/1000);stage.textContent=`${bytes(e.loaded)} of ${bytes(e.total)} transferred · ${bytes(e.loaded/elapsed)}/s`;};
xhr.upload.onload=()=>{bar.value=100;label.textContent='Upload sent — processing';stage.textContent='The server is saving the original archive and analyzing its logs. Keep this page open; large archives can take several minutes.';cancel.disabled=true;$('analysis-submit').textContent='Saving & analyzing…';};
xhr.onload=()=>{finish();let result;try{result=JSON.parse(xhr.responseText);}catch{}if(xhr.status>=200&&xhr.status<300&&result){bar.value=100;label.textContent='Upload saved — analysis complete';stage.textContent='Your original archive and ingestion results are retained in the data lake.';resolve(result);}else{label.textContent='Upload could not be processed';stage.textContent='See the error below. Archives received by the server are retained even if analysis fails.';reject(new Error(typeof result?.detail==='string'?result.detail:JSON.stringify(result?.detail||`Request failed (${xhr.status})`)));}};
xhr.onerror=()=>{finish();label.textContent='Connection lost';stage.textContent='If transfer completed, check the data lake before retrying.';reject(new Error('The upload connection was lost. Check the service connection and retry.'));};
xhr.onabort=()=>{finish();label.textContent='Upload canceled';stage.textContent='Transfer stopped. You can select a file and try again.';reject(new Error('Upload canceled.'));};xhr.send(form);});}
$('upload-cancel').addEventListener('click',()=>{if(activeEvidenceUpload&&!$('upload-cancel').disabled)activeEvidenceUpload.abort();});

async function openSavedAnalysis(id){showView('troubleshoot');setError($('analysis-error'),null);$('analysis-results').textContent='Loading saved report…';try{workflow.analysis=await api(`/api/analyses/${encodeURIComponent(id)}`);analysisTab('checks');$('analysis-results').scrollIntoView({block:'start'});}catch(error){$('analysis-results').textContent='';setError($('analysis-error'),error.message);}}
const savedAnalysisId=new URLSearchParams(window.location.search).get('analysis');
if(savedAnalysisId)openSavedAnalysis(savedAnalysisId);

async function loadReceivedEvidence(host){try{const data=await api('/api/lake/received');if(!host.isConnected)return;let section=$('received-upload-status');if(!section){section=document.createElement('section');section.id='received-upload-status';host.before(section);}section.innerHTML=`<div class="section-header"><div><h2>Received archives & recovery</h2><p>Original evidence retained on the server, including uploads still being processed. Refreshes every 15 seconds while this page is open.</p></div></div><div class="table-wrap"><table><thead><tr><th>Archive</th><th>Processing status</th><th>Evidence indexed</th><th>Report</th></tr></thead><tbody>${data.items.map(item=>{const r=item.recovery||{};return `<tr><td>${esc(item.filename)}<small class="block">${bytes(item.size_bytes)} · ${esc(item.received_at||'')}</small><small class="block receipt-hash">SHA-256 ${esc(item.sha256)}</small></td><td>${esc(r.stage||'Original retained')}<small class="block">${r.elapsed_seconds!=null?`${num(r.elapsed_seconds)} seconds elapsed`:''}</small></td><td>${num(r.scanned_log_files??0)} logs scanned<small class="block">${num(r.indexed_runs??0)} runs indexed</small></td><td>${r.analysis_id?`<a class="secondary small" href="?analysis=${encodeURIComponent(r.analysis_id)}">Open saved report ↗</a>`:'Processing / review pending'}</td></tr>`;}).join('')||'<tr><td colspan="4">No received archives.</td></tr>'}</tbody></table></div>`;}catch(error){/* Older services may not expose archive recovery yet. */}}

function measuredPerformance(r){return `${r.tflops_gpu!=null?`${num(r.tflops_gpu,2)} TFLOP/s/GPU · mean`:r.peak_bus_bw_gbps!=null?`${num(r.peak_bus_bw_gbps,2)} GB/s`:'No throughput summary'}${r.mean_step_time_ms!=null?`<small class="block">${num(r.mean_step_time_ms,2)} ms / step</small>`:''}${performanceCompact(performanceOf(r))}`;}
function trainingPerformance(c){const rows=c.best_training_performance||[];return `<h3>Best measured training performance by configuration</h3><p class="form-note">Completed source-backed training only. Models, precision, scale and recorded source configuration stay separate. Showing ${num(rows.length)} of ${num(c.training_configurations??rows.length)} configurations. These results do not assert NCCL correctness.</p><div class="table-wrap"><table><thead><tr><th>Workload / GPU / fabric</th><th>Scale / configuration</th><th>Measured performance</th><th>Source evidence</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.workload)}<small class="block">${esc(r.hardware||'Unknown')} · ${esc(r.transport||'Unknown')}</small></td><td>${num(r.nodes)} nodes / ${num(r.gpus)} GPUs<small class="block wrap-cell">${esc(JSON.stringify(r.configuration))}</small></td><td>${measuredPerformance(r)}</td><td><button class="secondary small" data-evidence-run="${esc(r.id)}">Inspect source ↗</button><small class="block receipt-hash">SHA-256 ${esc(r.source_sha256||'See source record')}</small></td></tr>`).join('')||'<tr><td colspan="4">No complete measured training results yet.</td></tr>'}</tbody></table></div>`;}

function performanceOf(result){return result?.performance_assessment||result?.performance||result?.training_performance||null;}
function performanceRating(value){const kind=value==='failed'?'worst':['good','bad','worst'].includes(value)?value:'unknown';return `<span class="performance-rating ${kind}">${esc(value||'unknown')}</span>`;}
function referenceSourceLink(url,label='Open source ↗'){if(!url)return '';try{const parsed=new URL(url,location.origin);if(!['http:','https:'].includes(parsed.protocol))return '';return `<a href="${esc(parsed.href)}" target="_blank" rel="noreferrer">${esc(label)}</a>`;}catch{return '';}}
function performanceMetricName(metric){return {tflops_gpu:'TFLOP/s/GPU',seconds_per_step:'s / step',busbw_gbps:'Bus bandwidth (GB/s)',algbw_gbps:'Algorithm bandwidth (GB/s)',time_us:'Latency (µs)'}[metric]||metric;}
function performanceCompact(p){if(!p)return '';if(isNcclPerformance(p))return ncclSummaryChip(p);const metrics=[...(p.metrics||[])].sort((a,b)=>(a.expected_pct??Infinity)-(b.expected_pct??Infinity));return `<div>${performanceRating(p.classification)}${metrics.slice(0,2).map(m=>`<small class="block">${num(m.expected_pct,1)}% of expected ${esc(metricPointLabel(m))}${m.scored?'':` · ${esc(m.performance_band||'unknown')} band, contextual only`}</small>`).join('')}${metrics.length>2?`<small class="block">Worst 2 of ${num(metrics.length)} measurement points; open comparison for details.</small>`:''}</div>`;}
function performanceAssessment(p,run=null){if(run?.workload==='NCCL'||isNcclPerformance(p))return renderNcclSimpleAssessment(p,run);if(!p)return '';const refs=p.references||[],metrics=p.metrics||[];return `<section class="performance-assessment finding"><div class="section-header"><div><h3>Production performance assessment</h3><p>Match quality: ${esc(p.tier||'none')} · ${p.verdict==='pass'?'Compatible reference target met':p.verdict==='fail'?'Result needs attention':'Reference evidence incomplete'}</p></div>${performanceRating(p.classification)}</div>${metrics.length>100?`<p class="form-note">Showing 100 of ${num(metrics.length)} measurement points. All points remain retained in the saved report.</p>`:''}<div class="performance-reference-grid">${metrics.slice(0,100).map(m=>`<div><span>${comparisonStatistic(p)} ${esc(performanceMetricName(m.metric))}</span>${m.message_bytes!=null?`<small>${esc(metricPointLabel(m))}</small>`:''}<strong>${benchmarkNumber(m.observed)}</strong><small>Reference ${esc(p.policy?.reference_statistic||'median')}: ${benchmarkNumber(m.expected)} ${esc(m.unit||performanceMetricName(m.metric))}</small>${m.reference_min!=null&&m.reference_max!=null?`<small>Reference range ${benchmarkNumber(m.reference_min)}–${benchmarkNumber(m.reference_max)} · ${num(m.reference_jobs)} source jobs</small>`:''}<small>${num(m.expected_pct,1)}% of expected · ${m.deficit_pct!=null?`${num(Math.abs(m.deficit_pct),1)}% ${m.deficit_pct>0?'below':'above'} expected performance`:'Difference unknown'}</small><small>${m.scored?'Scored against a compatible reference':`Contextual comparison — ${esc(m.performance_band||'unknown')} arithmetic band, not scored`}</small></div>`).join('')}</div>${p.missing_context?.length?`<div class="info-box"><strong>Missing context</strong><p>${p.missing_context.map(esc).join(' · ')}</p></div>`:''}${p.mismatches?.length?`<div class="evidence-warning">Configuration differences: ${p.mismatches.map(v=>esc(typeof v==='object'?JSON.stringify(v):v)).join(' · ')}</div>`:''}<div class="reference-provenance"><h4>Reference provenance</h4>${refs.length?refs.slice(0,20).map(r=>`<p>${referenceSourceLink(r.source_url,r.source_record_id||r.ref_id||'Source result ↗')}<small>Job ${esc(r.job_id||r.source_record_id||'Not recorded')} · ${esc(r.cluster||'Cluster not recorded')} · Release ${esc(r.release||r.software_release||'not recorded')}</small></p>`).join(''):'<p>No compatible production reference. Import a reviewed source result to score this configuration.</p>'}</div>${p.recommendations?.length?`<div class="performance-plan"><h4>Investigation plan</h4>${p.recommendations.slice(0,20).map(t=>`<details><summary>${esc(t.title)}</summary><p>${esc(t.reason)}</p>${t.command?`<pre class="code-panel">${esc(t.command)}</pre>`:''}<p><strong>Expected outcome: </strong>${esc(t.expected||'Collect comparable measurements and review evidence.')}</p>${t.rollback?`<p><strong>Scope / rollback: </strong>${esc(t.rollback)}</p>`:''}</details>`).join('')}</div>`:''}</section>`;}
function performanceOverview(a){const measured=(a.comparisons||[]).filter(hasMeasurements);if(measured.length&&measured.every(c=>c.run?.workload==='NCCL'))return '<section class="performance-assessment"><h3>NCCL bandwidth comparison</h3><p>Compare your 16 and 32 GiB results with the best recorded bandwidth for the matching configuration.</p></section>';const assessed=(a.comparisons||[]).filter(c=>performanceOf(c)),summary=a.performance||{};if(!assessed.length&&!summary.ratings)return performanceAssessment(performanceOf(a));const counts=assessed.length?assessed.reduce((out,c)=>{const k=performanceOf(c).classification||'unknown';out[k]=(out[k]||0)+1;return out;},{}):summary.ratings;const source=summary.source_status,sourceText=typeof source==='object'?source?.status||source?.beacon?.status:source;return `<section class="performance-assessment"><h3>Production reference performance</h3><p>Ratings use compatible production references. Conditional and unknown results need more context before acceptance.</p><div class="badge-row">${Object.entries(counts).filter(([,v])=>v).map(([k,v])=>`<span>${performanceRating(k)} ${num(v)} runs</span>`).join('')}</div>${sourceText?`<p>Reference source: ${esc(sourceText)} · ${num(summary.reference_count)} available records. <button class="secondary small" type="button" onclick="showView('lake')">Open reference library ↗</button></p>`:''}<p class="form-note">Good: up to ${num(summary.policy?.good_pct??5)}% below expected; bad: up to ${num(summary.policy?.bad_pct??10)}% below; worst: a larger deficit. Open Performance comparison for expected values, reference sources and investigation commands.</p></section>`;}


let performanceLibraryLoading=false;
let performanceReferenceOffset=0;
async function loadPerformanceLibrary(){if(performanceLibraryLoading)return;performanceLibraryLoading=true;setError($('performance-reference-error'),null);const params=new URLSearchParams({limit:100,offset:performanceReferenceOffset});for(const [key,value] of new FormData($('performance-reference-filters')))if(String(value).trim())params.set(key,String(value).trim());const results=await Promise.allSettled([api('/api/performance/status'),api(`/api/performance/references?${params}`)]);try{if(results[0].status==='fulfilled')renderPerformanceSources(results[0].value);else $('performance-source-status').textContent=`Reference source status unavailable: ${results[0].reason.message}`;if(results[1].status==='fulfilled')renderPerformanceReferences(results[1].value);else setError($('performance-reference-error'),results[1].reason.message);}finally{performanceLibraryLoading=false;}}
function renderPerformanceSources(data){updateNcclRemoteJob(data.jobs||[]);const source=data.beacon||data||{},instructions=Array.isArray(source.instructions)?source.instructions.join(' '):source.instructions;const ready=source.authenticated===true||Number(source.records)>0;let text=source.authenticated===true?'Connected to BEACON':Number(source.records)>0?'BEACON reference snapshot available':'BEACON source access required';$('performance-source-status').innerHTML=`<div class="info-box"><strong>${esc(text)}</strong><p>${esc(source.status||'Status unknown')} · ${num(source.records??0)} reference records · Last sync ${esc(source.last_sync||'not recorded')}</p>${source.gpu_types?.length?`<p>GPU coverage: ${source.gpu_types.map(esc).join(' · ')}</p>`:''}${source.error?`<p>${esc(source.error)}</p>`:''}${instructions?`<p>${esc(instructions)}</p>`:!ready?'<p>Provide an authorized BEACON reference export using the import form below. Source availability is separate from uploaded customer validation evidence.</p>':''}</div>${data.nccl?`<div class="info-box"><strong>NCCL source coverage</strong><p>${num(data.nccl.records)} historical measured records · ${(data.nccl.gpu_types||[]).map(esc).join(' · ')||'GPU coverage not recorded'}</p><p>${esc(data.nccl.source||'Exact protocol and configuration are required for scoring.')}</p></div>`:''}`;}
function referenceValues(r){const metrics=r.metrics||{};const t=r.tflops_gpu??metrics.tflops_gpu;const seconds=r.seconds_per_step??metrics.seconds_per_step;return `${t!=null?`${num(t,2)} TFLOP/s/GPU`:''}${seconds!=null?`<small class="block">${num(seconds,3)} s / step</small>`:''}${t==null&&seconds==null?'See source result':''}`;}
function renderPerformanceReferences(data){const rows=data.items||[],facets=data.facets||{};$('performance-reference-previous').disabled=performanceReferenceOffset===0;$('performance-reference-next').disabled=performanceReferenceOffset+rows.length>=(data.total??rows.length);for(const [key,values] of Object.entries(facets)){const input=$('performance-reference-filters').elements.namedItem(key);if(!input||!Array.isArray(values))continue;const id=`performance-reference-${key}-choices`;let choices=$(id);if(!choices){choices=document.createElement('datalist');choices.id=id;document.body.append(choices);}choices.innerHTML=values.map(value=>`<option value="${esc(typeof value==='object'?value.value??value.name:value)}"></option>`).join('');input.setAttribute('list',id);}$('performance-reference-results').innerHTML=`${referenceSnapshotDownload(data.snapshot)}<p class="form-note">Showing ${num(rows.length)} of ${num(data.total??rows.length)} production reference records${rows.length?` (records ${num(performanceReferenceOffset+1)}–${num(performanceReferenceOffset+rows.length)})`:''}${data.snapshot?` · Snapshot ${esc(typeof data.snapshot==='object'?data.snapshot.release||data.snapshot.snapshot_id||data.snapshot.id||'current':data.snapshot)}`:''}. Filter to inspect another configuration. Customer uploads become observations until reviewed.</p><div class="table-wrap"><table><thead><tr><th>GPU / workload</th><th>Precision / scale / release</th><th>Reference measurements</th><th>Source provenance</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.gpu||r.hardware||r.gpu_type||'Unknown GPU')}<small class="block">${esc(r.workload||r.model||'Unknown workload')}</small></td><td>${esc(r.precision||r.dtype||'Unknown precision')} · ${num(r.scale||r.gpus||r.num_gpus)} GPUs<small class="block">${esc(r.release||r.software_release||'Release not recorded')}</small></td><td>${referenceValues(r)}</td><td class="reference-provenance">${referenceSourceLink(r.row_action||r.source_url||r.url,r.source_record_id||r.ref_id||r.id||'Open source ↗')}<small>Job ${esc(r.job_id||r.source_record_id||'not recorded')} · ${esc(r.cluster||'Cluster not recorded')}</small></td></tr>`).join('')||'<tr><td colspan="4">No matching production references. Connect a source or import an authorized reference export.</td></tr>'}</tbody></table></div>`;}
$('performance-library-refresh').addEventListener('click',loadPerformanceLibrary);
$('performance-reference-filters').addEventListener('submit',event=>{event.preventDefault();performanceReferenceOffset=0;loadPerformanceLibrary();});
$('performance-reference-import').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,file=form.elements.manifest.files[0],button=form.querySelector('button'),message=$('performance-import-message');if(!file)return;button.disabled=true;message.textContent='Importing reference export…';try{const body=new FormData();body.append('file',file);const result=await api('/api/performance/import',{method:'POST',body});message.textContent=`Reference import complete. ${num(result.imported??result.records??result.count)} records imported.`;await loadPerformanceLibrary();const reassessmentId=performanceJobId(result.reassessment||{});if(reassessmentId){message.textContent+=' Reassessing saved investigations…';await monitorPerformanceJob(reassessmentId,(job,state)=>{message.textContent=performanceJobMessage(job,`Reference import saved; reassessment: ${state}`);});message.textContent='Reference import and saved-investigation reassessment complete.';}}catch(error){message.textContent=error.message;}finally{button.disabled=false;}});
function renderInvestigation(plan){if(!plan?.findings?.length)return '';return `<section class="performance-assessment"><h3>Evidence-based investigation plan</h3><p>${esc(plan.summary||'')}</p><p class="form-note">${esc(plan.evidence_state||'')}</p>${plan.findings.slice(0,100).map(f=>`<article class="finding performance-plan"><h4>${esc(f.title)}</h4><p>${esc(f.trigger||'')}</p><p>${esc(f.why||'')}</p>${f.evidence?.length?`<details><summary>Evidence (${num(f.evidence.length)})</summary><pre class="code-panel">${esc(JSON.stringify(f.evidence.slice(0,20),null,2))}</pre></details>`:''}${f.commands?.length?`<pre class="code-panel">${esc(f.commands.map(c=>typeof c==='string'?c:JSON.stringify(c)).join('\n'))}</pre>`:''}<p><strong>Expected outcome: </strong>${esc(f.expected||'')}</p>${f.rollback?`<p><strong>Scope / rollback: </strong>${esc(f.rollback)}</p>`:''}${f.applicability?`<p>Applies to: ${esc(typeof f.applicability==='object'?JSON.stringify(f.applicability):f.applicability)}</p>`:''}${f.cautions?.length?`<p>${f.cautions.map(esc).join(' · ')}</p>`:''}${f.source_urls?.length?`<p>${f.source_urls.map(url=>referenceSourceLink(url)).join(' · ')}</p>`:''}</article>`).join('')}</section>`;}

function updateScriptTuningControls(){const recipe=workflow.recipes.find(p=>p.id===$('script-recipe').value),allowed=recipe?.fabric==='spectrum-x'&&$('script-collective').value==='alltoall';const preset=$('script-tuning-preset');preset.disabled=!allowed;for(const option of preset.options)option.disabled=option.value!=='defaults'&&!allowed;if(!allowed)preset.value='defaults';}
$('script-collective').addEventListener('change',updateScriptTuningControls);

const performanceReassessState=new Map();
let performanceSyncActive=false;
function performanceJobId(result){return result.job_id||result.id||result.job?.id||result.job?.job_id;}
function performanceJobStatus(job){return String(job?.status||job?.state||job?.stage||'queued').toLowerCase();}
function performanceJobFromStatus(data,id){const jobs=data.jobs||data.background_jobs||[];if(Array.isArray(jobs))return jobs.find(job=>(job.job_id||job.id)===id);return jobs[id]||Object.values(jobs).find(job=>(job.job_id||job.id)===id);}
async function monitorPerformanceJob(id,onProgress){for(let attempt=0;attempt<600;attempt++){const data=await api('/api/performance/status'),job=performanceJobFromStatus(data,id);if(job){const state=performanceJobStatus(job);onProgress(job,state);if(['complete','completed','succeeded','success','done'].includes(state))return job;if(['partial','failed','error','canceled','cancelled'].includes(state))throw new Error(job.details?.error||job.error||job.message||`Job ${state}${job.details?.completed!=null?` — ${num(job.details.completed)} of ${num(job.details.total)} completed`:''}. Review the latest report and source status before retrying.`);}await new Promise(resolve=>setTimeout(resolve,3000));}throw new Error('Processing continues on the server. Refresh the reference library or saved report to check the latest result.');}
function updateReassessControls(){const button=document.querySelector('[data-performance-reassess]');if(!button)return;const current=performanceReassessState.get(button.dataset.performanceReassess);button.disabled=!!current?.active;const message=document.querySelector('[data-performance-reassess-message]');if(message)message.textContent=current?.message||'';}
$('analysis-results').addEventListener('click',async event=>{const button=event.target.closest('[data-performance-reassess]');if(!button)return;const id=button.dataset.performanceReassess;if(performanceReassessState.get(id)?.active)return;const progress={active:true,message:'Queueing reassessment against the latest reference snapshot…'};performanceReassessState.set(id,progress);updateReassessControls();try{const result=await api(`/api/performance/reassess?analysis_id=${encodeURIComponent(id)}`,{method:'POST'}),jobId=performanceJobId(result);if(jobId){progress.message='Reassessment queued. Your original evidence stays retained.';updateReassessControls();await monitorPerformanceJob(jobId,(job,state)=>{progress.message=performanceJobMessage(job,`Reassessment: ${state}`);updateReassessControls();});}else if(!['complete','completed','succeeded','success','done'].includes(performanceJobStatus(result)))throw new Error('The server accepted the request without a job identifier. Refresh the saved report to check the result.');progress.message='Reassessment complete — latest reference results loaded.';if(workflow.analysis?.id===id){workflow.analysis=await api(`/api/analyses/${encodeURIComponent(id)}`);renderAnalysis();}}catch(error){progress.message=error.message;}finally{progress.active=false;updateReassessControls();}});
$('performance-source-sync').addEventListener('click',async()=>{if(performanceSyncActive)return;performanceSyncActive=true;const button=$('performance-source-sync'),message=$('performance-sync-message');button.disabled=true;message.textContent='Queueing BEACON reference sync…';try{const result=await api('/api/performance/sync',{method:'POST'}),id=performanceJobId(result);if(id)await monitorPerformanceJob(id,(job,state)=>{message.textContent=performanceJobMessage(job,`BEACON sync: ${state}`);});else if(!['complete','completed','succeeded','success','done','synced'].includes(performanceJobStatus(result)))throw new Error(result.message||'Sync accepted. Refresh the reference library to check its latest status.');message.textContent='BEACON sync complete. Reference library refreshed.';await loadPerformanceLibrary();}catch(error){message.textContent=error.message;}finally{performanceSyncActive=false;button.disabled=false;}});

function performanceJobMessage(job,fallback){const details=job.details||{},progress=details.progress||{},phase=details.phase||progress.stage,completed=details.completed??progress.runs,total=details.total??progress.total,elapsed=progress.elapsed_seconds??progress.elapsed;return job.message||`${fallback}${phase?` · ${phase}`:''}${completed!=null&&total!=null?` · ${num(completed)} of ${num(total)}`:''}${details.records!=null?` · ${num(details.records)} records`:''}${typeof elapsed==='number'?` · ${num(elapsed)} seconds elapsed`:''}`;}

function referenceSnapshotDownload(snapshot){const id=snapshot?.snapshot_id||snapshot?.id;if(!snapshot?.metadata?.compact_sha256||!id)return '';return `<p><a class="secondary small" href="/api/performance/snapshot/${encodeURIComponent(id)}" download>Download reference snapshot (.jsonl.gz)</a></p><p class="form-note receipt-hash">SHA-256 ${esc(snapshot.metadata.compact_sha256)}</p>`;}

$('performance-reference-previous').addEventListener('click',()=>{if(performanceLibraryLoading)return;performanceReferenceOffset=Math.max(0,performanceReferenceOffset-100);loadPerformanceLibrary();});
$('performance-reference-next').addEventListener('click',()=>{if(performanceLibraryLoading)return;performanceReferenceOffset+=100;loadPerformanceLibrary();});

function comparisonStatistic(p){const statistic=p?.policy?.observed_statistic;if(!statistic&&p?.metrics?.some(m=>['busbw_gbps','algbw_gbps','time_us'].includes(m.metric)))return 'Observed';return statistic==='mean'?'Mean':statistic==='best'?'Best':'Median';}
function inlineContextLabel(value){return {gpu:'verified GPU',gpus:'GPU count',sequence_length:'sequence length',release:'release',model_size:'model size',recorded_environment:'NCCL environment',nccl_tests_version:'nccl-tests version'}[value]||String(value).replace(/_/g,' ');}
function runPerformanceInline(r){const p=performanceOf(r);if(r.workload==='NCCL')return ncclSummaryChip(p);if(!p)return '<div class="inline-performance"><span class="performance-rating unknown">Unknown reference</span><small class="inline-performance-context">No benchmark assessment for this configuration.</small></div>';const metrics=[...(p.metrics||[])].sort((a,b)=>(a.expected_pct??Infinity)-(b.expected_pct??Infinity)).slice(0,2),conditional=p.classification==='conditional'||metrics.some(m=>m.scored===false)&&p.classification!=='failed',band=p.candidate_band||metrics.find(m=>m.performance_band)?.performance_band||p.classification,known=['good','bad','worst'].includes(band);const total=p.point_count??p.provenance?.point_count??p.metrics?.length??0;const label=p.classification==='failed'?'Failed run':conditional&&known?`${band} band · conditional`:known?band:'Unknown reference';const style=p.classification==='failed'?'worst':conditional?'unknown':known?band:'unknown';return `<div class="inline-performance"><span class="performance-rating ${style}">${esc(label)}</span>${metrics.map(m=>{const delta=m.delta_pct??(m.expected_pct!=null?m.expected_pct-100:null),direction=delta==null?'':delta===0?'Matches reference':`${num(Math.abs(delta),1)}% ${delta>0?'better':'worse'} than reference`;return `<div class="inline-performance-metric"><strong class="${delta==null?'':delta<0?'delta-worse':'delta-better'}">${esc(metricPointLabel(m))} · ${esc(direction||'Difference unknown')}${m.expected_pct!=null?` · ${num(m.expected_pct,1)}% expected`:''}</strong><small>${comparisonStatistic(p)} ${benchmarkNumber(m.observed)} vs reference ${benchmarkNumber(m.expected)} ${esc(m.unit||performanceMetricName(m.metric))}</small></div>`;}).join('')}${total>metrics.length?`<small class="inline-performance-context">Worst ${num(metrics.length)} of ${num(total)} comparisons shown.</small>`:''}${conditional?'<small class="inline-performance-context">Contextual comparison · acceptance not established.</small>':''}${p.missing_context?.length?`<small class="inline-performance-context">Missing: ${p.missing_context.slice(0,3).map(v=>esc(inlineContextLabel(v))).join(', ')}${p.missing_context.length>3?` +${num(p.missing_context.length-3)} more`:''}</small>`:''}${p.mismatches?.length?`<small class="inline-performance-context">Different: ${p.mismatches.slice(0,3).map(v=>esc(inlineContextLabel(v))).join(', ')}</small>`:''}</div>`;}
function benchmarkStatisticNote(r){const p=performanceOf(r),throughput=p?.metrics?.find(m=>m.metric==='tflops_gpu');if(!throughput)return '';return `The benchmark compares the ${comparisonStatistic(p).toLowerCase()} (${num(throughput.observed,2)} TFLOP/s/GPU) with the source reference; it can differ from the arithmetic mean shown above.`;}

function metricPointLabel(metric){const name={tflops_gpu:'Throughput',seconds_per_step:'Step time',busbw_gbps:'Bus BW',algbw_gbps:'Algorithm BW',time_us:'Latency'}[metric.metric]||metric.metric;return `${name}${metric.message_bytes!=null?` · ${bytes(metric.message_bytes)}`:''}${metric.placement?` · ${String(metric.placement).replace(/_/g,' ')}`:''}`;}
let ncclReferenceLoading=false,ncclReferenceOffset=0,ncclReassessActive=false,ncclRemoteReassessActive=false;
async function loadNcclReferenceLibrary(){if(ncclReferenceLoading)return;ncclReferenceLoading=true;setError($('nccl-reference-error'),null);const params=new URLSearchParams({limit:100,offset:ncclReferenceOffset});for(const [key,value] of new FormData($('nccl-reference-filters')))if(String(value).trim())params.set(key,String(value).trim());const results=await Promise.allSettled([api('/api/performance/nccl/status'),api(`/api/performance/nccl/references?${params}`)]);try{if(results[0].status==='fulfilled')renderNcclReferenceStatus(results[0].value);else $('nccl-reference-status').textContent=`NCCL source status unavailable: ${results[0].reason.message}`;if(results[1].status==='fulfilled')renderNcclReferences(results[1].value);else setError($('nccl-reference-error'),results[1].reason.message);}finally{ncclReferenceLoading=false;}}
function renderNcclReferenceStatus(data){const imported=Number(data.records)||0,count=data.measured_records!=null?Number(data.measured_records)||0:null;const gaps=[];if(imported&&!(data.gpu_types||[]).some(g=>String(g).toUpperCase()==='B300'))gaps.push('No external B300 NCCL baseline is present in this snapshot.');if(imported&&!(data.networks||[]).some(f=>/spectrum[ _-]?x/i.test(f)))gaps.push('Spectrum-X-specific recipe evidence is unavailable; generic RoCE coverage requires additional recipe context.');$('nccl-reference-status').innerHTML=`<div class="info-box"><strong>${count?'Measured NCCL references imported':imported?'NCCL references imported':'Waiting for measured NCCL references'}</strong><p>${count!=null?`${num(count)} ready measured reference records · `:''}${num(imported)} imported records · ${esc(data.status||'Status unavailable')}</p>${imported?`<p>GPU coverage: ${(data.gpu_types||[]).map(esc).join(' · ')||'not recorded'}<br>Fabrics: ${(data.networks||[]).map(esc).join(' · ')||'not recorded'}</p><p>Latest source snapshot ${esc(data.snapshot?.created_at||'See source snapshot')} · ${referenceSourceLink(data.snapshot?.source_url,'Open reference source ↗')}</p>`:`<p>${esc(data.instructions||'Import an actual NCCL export with source provenance to enable this reference library.')}</p>${data.discovery?.finding?`<details><summary>Source discovery status</summary><p>${esc(data.discovery.finding)}</p></details>`:''}`}${gaps.length?`<p><strong>Coverage gaps:</strong> ${gaps.map(esc).join(' ')}</p>`:''}<p class="form-note">Ready totals count imported measurements across active sources. Source discovery metadata and training TFLOPs are not NCCL reference measurements.</p></div>${renderNcclSourceSnapshots(data)}`;}
function ncclReferencePoint(point){const values=[['busbw_gbps','Bus BW','GB/s'],['algbw_gbps','Algorithm BW','GB/s'],[point.latency_us!=null?'latency_us':'time_us','Latency','µs']].filter(([key])=>point[key]!=null).map(([key,label,unit])=>`${label} ${benchmarkNumber(point[key])} ${unit}`).join(' · ');return `<small class="block">${point.message_bytes!=null?`${bytes(point.message_bytes)} · `:''}${esc(String(point.placement||'placement not recorded').replace(/_/g,' '))}</small><small class="block">${values||'No measured values'}</small>`;}
function renderNcclReferences(data){const rows=data.items||[];$('nccl-reference-previous').disabled=ncclReferenceOffset===0;$('nccl-reference-next').disabled=ncclReferenceOffset+rows.length>=(data.total??rows.length);for(const [key,values] of Object.entries(data.facets||{})){const input=$('nccl-reference-filters').elements.namedItem(key);if(!input||!Array.isArray(values))continue;const id=`nccl-reference-${key}-choices`;let list=$(id);if(!list){list=document.createElement('datalist');list.id=id;document.body.append(list);}list.innerHTML=values.map(v=>`<option value="${esc(v)}"></option>`).join('');input.setAttribute('list',id);}$('nccl-reference-results').innerHTML=`<p class="form-note">Showing ${num(rows.length)} of ${num(data.total??rows.length)} imported NCCL reference records${rows.length?` (records ${num(ncclReferenceOffset+1)}–${num(ncclReferenceOffset+rows.length)})`:''}.</p><div class="table-wrap"><table><thead><tr><th>GPU / scale</th><th>Fabric / collective / NCCL</th><th>Measured point preview</th><th>Source provenance</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.gpu||'Unknown GPU')}<small class="block">${num(r.gpus)} GPUs${r.nodes?` · ${num(r.nodes)} nodes`:''}</small></td><td>${esc(r.fabric||'Fabric not recorded')}<small class="block">${esc(r.collective||'Collective not recorded')} · NCCL ${esc(r.nccl_version||'not recorded')}</small></td><td>${(r.metric_preview||r.metrics||[]).slice(0,3).map(ncclReferencePoint).join('')}${(r.metric_points??r.metrics?.length??0)>0?`<small class="block">${num(r.metric_points??r.metrics?.length)} measured points retained; open the source for the full curve.</small>`:'<small class="block">No measured curve points recorded.</small>'}</td><td>${referenceSourceLink(r.row_action||r.source_url,r.source_record_id||r.job_id||r.ref_id||'Open source ↗')}<small class="block">Job ${esc(r.job_id||'not recorded')} · ${esc(r.cluster||'Cluster not recorded')}</small></td></tr>`).join('')||'<tr><td colspan="4">No imported measured NCCL references match these filters.</td></tr>'}</tbody></table></div>`;}
$('nccl-library-refresh').addEventListener('click',loadNcclReferenceLibrary);
$('nccl-reference-filters').addEventListener('submit',event=>{event.preventDefault();ncclReferenceOffset=0;loadNcclReferenceLibrary();});
$('nccl-reference-previous').addEventListener('click',()=>{if(ncclReferenceLoading)return;ncclReferenceOffset=Math.max(0,ncclReferenceOffset-100);loadNcclReferenceLibrary();});
$('nccl-reference-next').addEventListener('click',()=>{if(ncclReferenceLoading)return;ncclReferenceOffset+=100;loadNcclReferenceLibrary();});
$('nccl-library-reassess').addEventListener('click',async()=>{if(ncclReassessActive||ncclRemoteReassessActive)return;ncclReassessActive=true;const button=$('nccl-library-reassess'),message=$('nccl-reference-job-message');button.disabled=true;message.textContent='Queueing NCCL reassessment. Large histories can take several minutes.';try{const result=await api('/api/performance/nccl/reassess',{method:'POST'}),id=performanceJobId(result);if(!id)throw new Error('NCCL reassessment accepted without a job identifier. Check processing status before retrying.');await monitorPerformanceJob(id,(job,state)=>{message.textContent=performanceJobMessage(job,`NCCL reassessment: ${state}`);});message.textContent='NCCL reassessment complete. Refresh the explorer to see the latest ratings.';await loadNcclReferenceLibrary();}catch(error){message.textContent=error.message;}finally{ncclReassessActive=false;ncclRemoteReassessActive=false;button.disabled=false;loadPerformanceLibrary();}});
$('nccl-reference-import').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button'),file=form.elements.file.files[0],message=$('nccl-import-message');if(!file)return;button.disabled=true;message.textContent='Importing measured NCCL references…';try{const body=new FormData();body.append('file',file);const result=await api(`/api/performance/nccl/import?source_url=${encodeURIComponent(form.elements.source_url.value)}`,{method:'POST',body});message.textContent=`Imported ${num(result.imported)} NCCL reference records.`;await loadNcclReferenceLibrary();const id=performanceJobId(result.reassessment||{});if(id){message.textContent+=' Reassessing existing NCCL observations…';await monitorPerformanceJob(id,(job,state)=>{message.textContent=performanceJobMessage(job,`NCCL import saved; reassessment: ${state}`);});message.textContent='NCCL reference import and reassessment complete.';}}catch(error){message.textContent=error.message;}finally{button.disabled=false;}});

function updateNcclRemoteJob(jobs){const previous=ncclRemoteReassessActive,running=jobs.find(job=>job.kind==='nccl-reassess'&&['queued','running'].includes(performanceJobStatus(job)));ncclRemoteReassessActive=!!running;const button=$('nccl-library-reassess');if(button)button.disabled=ncclReassessActive||ncclRemoteReassessActive;if(running&&!ncclReassessActive)$('nccl-reference-job-message').textContent=performanceJobMessage(running,'NCCL reassessment already running');else if(previous&&!ncclReassessActive){const latest=jobs.find(job=>job.kind==='nccl-reassess');$('nccl-reference-job-message').textContent=latest?performanceJobStatus(latest)==='complete'?'NCCL reassessment complete. Refresh the explorer to see the latest ratings.':latest.details?.error||`NCCL reassessment: ${performanceJobStatus(latest)}`:'NCCL processing status changed. Refresh the explorer to check the latest results.';}}

function benchmarkNumber(value){return num(value,Number(value)!==0&&Math.abs(Number(value))<1?4:2);}

let confluenceSourceLoading=false,confluenceSourceOffset=0;
async function loadConfluenceSources(){if(confluenceSourceLoading)return;confluenceSourceLoading=true;setError($('confluence-source-error'),null);const params=new URLSearchParams({limit:100,offset:confluenceSourceOffset});for(const [key,value] of new FormData($('confluence-source-filters')))if(String(value).trim())params.set(key,String(value).trim());const results=await Promise.allSettled([api('/api/performance/confluence/status'),api(`/api/performance/confluence/sources?${params}`)]);try{if(results[0].status==='fulfilled')renderConfluenceSourceStatus(results[0].value);else $('confluence-source-status').textContent=`Confluence inventory status unavailable: ${results[0].reason.message}`;if(results[1].status==='fulfilled')renderConfluenceSources(results[1].value);else setError($('confluence-source-error'),results[1].reason.message);}finally{confluenceSourceLoading=false;}}
function renderConfluenceSourceStatus(data){const categories=data.categories||{},discovery=data.discovery||{};$('confluence-source-status').innerHTML=`<div class="info-box"><strong>${num(data.pages??0)} indexed guidance pages</strong>${data.reviewed_findings!=null?`<p>${num(data.reviewed_findings)} extracted guidance findings with versioned section and table evidence.</p>`:''}<p>${esc(data.access_method||'Versioned source evidence')}${data.read_only?' · Read-only source access':''} · Indexed ${esc(data.indexed_at||'not yet')}</p><p>${esc(data.scope||'Relevant validation and troubleshooting sources.')}</p><p>${esc(data.caveat||'Indexed pages are source guidance; page counts do not represent numeric benchmark baselines.')}</p>${Object.keys(categories).length?`<p>${Object.entries(categories).map(([key,count])=>`${esc(key)}: ${num(count)}`).join(' · ')}</p>`:''}${discovery.discovered_pages!=null?`<p>${num(discovery.discovered_pages)} relevant pages discovered during topic searches; the indexed page total above counts downloaded versioned source evidence.</p>`:''}</div>`;}
function renderConfluenceSources(data){const rows=data.items||[],select=$('confluence-source-filters').elements.category,selected=select.value;select.innerHTML='<option value="">All categories</option>'+(data.facets?.category||[]).map(category=>`<option value="${esc(category)}">${esc(category)}</option>`).join('');select.value=selected;$('confluence-source-previous').disabled=confluenceSourceOffset===0;$('confluence-source-next').disabled=confluenceSourceOffset+rows.length>=(data.total??rows.length);$('confluence-source-results').innerHTML=`<p class="form-note">Showing ${num(rows.length)} of ${num(data.total??rows.length)} matching indexed pages${rows.length?` (sources ${num(confluenceSourceOffset+1)}–${num(confluenceSourceOffset+rows.length)})`:''}. GPU mentions describe document scope and do not qualify a measured baseline.</p><div class="table-wrap"><table><thead><tr><th>Source document</th><th>Category / GPU mentions</th><th>Version / updated</th><th>Evidence receipt</th></tr></thead><tbody>${rows.map(page=>`<tr><td>${referenceSourceLink(page.url,page.title||page.page_id)}<small class="block">${esc(page.excerpt||'Open the source for full context.')}</small></td><td>${esc(page.category||'reference guide')}<small class="block">${(page.gpus||[]).map(esc).join(' · ')||'No specific GPU recorded'}</small></td><td>Version ${num(page.version)}<small class="block">${esc(page.updated_at||'Date not recorded')}</small></td><td><details><summary>Page ${esc(page.page_id)} · version receipt</summary><p class="form-note receipt-hash">Body SHA-256 ${esc(page.body_sha256)}</p><p class="form-note receipt-hash">Payload SHA-256 ${esc(page.payload_sha256)}</p><p class="form-note">Indexed ${esc(page.indexed_at||'not recorded')}</p></details></td></tr>`).join('')||'<tr><td colspan="4">No indexed Confluence sources match these filters.</td></tr>'}</tbody></table></div>`;}
$('confluence-source-refresh').addEventListener('click',loadConfluenceSources);
$('confluence-source-filters').addEventListener('submit',event=>{event.preventDefault();confluenceSourceOffset=0;loadConfluenceSources();});
$('confluence-source-previous').addEventListener('click',()=>{if(confluenceSourceLoading)return;confluenceSourceOffset=Math.max(0,confluenceSourceOffset-100);loadConfluenceSources();});
$('confluence-source-next').addEventListener('click',()=>{if(confluenceSourceLoading)return;confluenceSourceOffset+=100;loadConfluenceSources();});

let confluenceKnowledgeLoading=false;
async function loadConfluenceKnowledge(){if(confluenceKnowledgeLoading)return;confluenceKnowledgeLoading=true;const host=$('confluence-knowledge-results');host.textContent='Loading source-backed guidance…';try{const params=new URLSearchParams({limit:50}),query=$('confluence-knowledge-query').value.trim();if(query)params.set('q',query);const result=await api(`/api/performance/confluence/knowledge?${params}`);renderConfluenceKnowledge(result);}catch(error){host.textContent=error.message;}finally{confluenceKnowledgeLoading=false;}}
function guidanceContext(context){if(!context||!Object.keys(context).length)return '';return `<dl class="detail-meta">${Object.entries(context).map(([key,value])=>`<div><dt>${esc(key.replace(/_/g,' '))}</dt><dd>${esc(Array.isArray(value)?value.join(', '):typeof value==='object'?JSON.stringify(value):value)}</dd></div>`).join('')}</dl>`;}
function renderConfluenceKnowledge(data){const rows=data.items||[];$('confluence-knowledge-results').innerHTML=`<p class="form-note">${num(rows.length)} of ${num(data.total??rows.length)} matching guidance findings. Source context remains required; automatic infrastructure changes are disabled.</p>${rows.map(f=>`<details class="finding"><summary>${esc(f.title||f.id)}</summary><p>${esc(f.summary||'')}</p>${guidanceContext(f.applicability)}${f.numeric_targets?.length?`<p><strong>Numeric source guidance:</strong> ${f.numeric_targets.map(t=>esc(`${String(t.metric||'metric').replace(/_/g,' ')} ${t.comparison==='less_than'?'<':t.comparison==='equals'?'=':''} ${t.value} ${t.unit||''}${t.qualification?` (${String(t.qualification).replace(/_/g,' ')})`:''}`)).join(' · ')}</p>`:''}${f.read_only_commands?.length?`<p><strong>Read-only diagnostics</strong></p><pre class="code-panel">${esc(f.read_only_commands.join('\n'))}</pre>`:''}${f.expected?`<p><strong>Expected outcome:</strong> ${esc(f.expected)}</p>`:''}${f.rollback?`<p><strong>Scope / rollback:</strong> ${esc(f.rollback)}</p>`:''}${f.requires_maintenance_plan?'<p>Fault-injection steps require a maintenance plan and restoration of the original state.</p>':''}${f.cautions?.length?`<p>${f.cautions.map(esc).join(' · ')}</p>`:''}<p><strong>Versioned source evidence</strong></p>${(f.evidence||[]).slice(0,10).map(e=>`<p>${referenceSourceLink(e.source_url,e.page_title||e.page_id||'Open source ↗')} · v${num(e.page_version)}<small class="block">${esc((e.section_path||[]).join(' → ')||'Page text')}${e.table_index!=null?` · Table ${num(e.table_index)}${e.rows?` · Rows ${e.rows.map(row=>row.row_index).join(', ')}`:''}`:''}</small></p>`).join('')}</details>`).join('')||'<p>No reviewed guidance matches this search.</p>'}`;}
$('confluence-reviewed-guidance').addEventListener('toggle',event=>{if(event.target.open)loadConfluenceKnowledge();});
$('confluence-knowledge-form').addEventListener('submit',event=>{event.preventDefault();loadConfluenceKnowledge();});

function renderNcclSourceSnapshots(data){if(!data.sources?.length)return '';return `<details class="context-inputs"><summary>${num(data.sources.length)} active NCCL source snapshots · ${num(data.metric_points)} measured points</summary><p class="form-note">Global measured totals include all active source snapshots below. The latest import alone does not represent the entire library.</p><div class="table-wrap"><table><thead><tr><th>Reference source</th><th>Imported / measured</th><th>Measurement points</th><th>Snapshot provenance</th></tr></thead><tbody>${data.sources.map(source=>`<tr><td>${referenceSourceLink(source.source_url,source.source_url||'Open source ↗')}</td><td>${num(source.records)} imported<small class="block">${num(source.measured_records)} measured</small></td><td>${num(source.metric_points)}</td><td>${esc(source.created_at||'Date not recorded')}<small class="block receipt-hash">${esc(source.snapshot_id)}</small></td></tr>`).join('')}</tbody></table></div></details>`;}

const NCCL_COMPARISON_SIZES=[16,32].map(gib=>gib*1024**3);
function isNcclPerformance(p){return !!(p?.nccl_summary||p?.metrics?.some(m=>['busbw_gbps','algbw_gbps','time_us'].includes(m.metric)));}
function ncclSimpleSummary(p,run=null){if(p?.nccl_summary){const summary=p.nccl_summary;return {...summary,rows:NCCL_COMPARISON_SIZES.map(size=>summary.rows?.find(row=>Number(row.message_bytes)===size)||{message_bytes:size,observed_gbps:null,reference_gbps:null,reference_status:'unavailable'})};}const metrics=p?.metrics||[],raw=run?.metrics||[];return {rows:NCCL_COMPARISON_SIZES.map(size=>{const points=metrics.filter(m=>m.metric==='busbw_gbps'&&Number(m.message_bytes)===size),recorded=raw.filter(m=>Number(m.message_bytes)===size&&Number.isFinite(m.busbw_gbps)&&!m.errors),observed=[...points.map(m=>m.observed),...recorded.map(m=>m.busbw_gbps)].filter(v=>v!=null&&Number.isFinite(Number(v)));return {message_bytes:size,observed_gbps:observed.length?Math.max(...observed):null,reference_gbps:null,reference_status:'unavailable'};}),improvements:[],context_note:'A matching best-recorded reference is unavailable for these sizes. Missing log points remain unavailable.'};}
function ncclDelta(row){if(row.observed_gbps==null||row.reference_gbps==null||Number(row.reference_gbps)<=0)return null;return row.delta_pct!=null?Number(row.delta_pct):100*(Number(row.observed_gbps)/Number(row.reference_gbps)-1);}
function ncclDeltaText(row){const delta=ncclDelta(row);return delta==null?'No comparison':Math.abs(delta)<.05?'Matches best':`${num(Math.abs(delta),1)}% ${delta>0?'over':'under'}`;}
function ncclSummaryChip(p){const rows=p?.nccl_summary?.rows||[],observed=rows.filter(row=>row.observed_gbps!=null);const failed=p?.classification==='failed'||p?.nccl_summary?.failed;const label=failed?'Failed run':p?.nccl_summary&&!observed.length?'No 16/32 GiB test':observed.some(row=>row.reference_gbps!=null)?'Compared with best':'Reference unavailable';return `<div class="nccl-summary-chip"><span class="performance-rating ${failed?'worst':'unknown'}">${label}</span></div>`;}
function ncclActualSizeNote(row){return row.actual_message_bytes!=null&&Number(row.actual_message_bytes)!==Number(row.message_bytes)?`Actual message: ${num(row.actual_message_bytes)} bytes (native count rounding); reference comparison uses these exact bytes.`:'';}
function ncclExplorerColumns(run){if(run.workload!=='NCCL')return NCCL_COMPARISON_SIZES.map(()=>'<td class="nccl-size-cell muted">—</td>').join('');const summary=ncclSimpleSummary(performanceOf(run),run);return summary.rows.map(row=>{const delta=ncclDelta(row),tooltip=`${row.message_bytes/1024**3} GiB · Best recorded: ${row.reference_gbps!=null?`${benchmarkNumber(row.reference_gbps)} GB/s`:'unavailable'}${row.placement?` · ${String(row.placement).replace(/_/g,' ')}`:''}${ncclActualSizeNote(row)?` · ${ncclActualSizeNote(row)}`:''}${summary.context_note?` · ${summary.context_note}`:''}`;return `<td class="nccl-size-cell" title="${esc(tooltip)}">${row.observed_gbps!=null?`<strong>${benchmarkNumber(row.observed_gbps)}</strong><small class="${delta!=null&&delta<0?'delta-worse':delta!=null?'delta-better':''}">${delta==null?'No reference':ncclDeltaText(row)}</small>`:'<span class="muted">—</span><small>Unavailable</small>'}</td>`;}).join('');}
function renderNcclSimpleAssessment(p,run=null){const summary=ncclSimpleSummary(p,run),defaults=[{title:'Match the reference setup',detail:'Use the same NCCL version, GPU count, fabric and placement.'},{title:'Repeat the same message sizes',detail:'Run the available 16 and 32 GiB sizes with identical warm-up and iteration settings.'},{title:'Isolate the slow path',detail:'Compare one node, a node pair, then the target scale.'},{title:'Change one setting at a time',detail:'Compare repeated runs and restore the original settings after each trial.'}],improvements=(summary.improvements?.length?summary.improvements:defaults).slice(0,4);return `<section class="performance-assessment nccl-simple-assessment"><h3>NCCL bandwidth compared with best recorded</h3><p class="form-note">GB/s is bandwidth. GiB is message size.${run?.nccl_version?` NCCL ${esc(run.nccl_version)}.`:''}</p><div class="table-wrap"><table class="nccl-simple-table"><thead><tr><th>Message size</th><th>Best recorded GB/s</th><th>Your GB/s</th><th>Over / under</th></tr></thead><tbody>${summary.rows.map(row=>{const delta=ncclDelta(row);return `<tr><td title="${esc(ncclActualSizeNote(row))}">${row.message_bytes/1024**3} GiB</td><td>${row.reference_gbps!=null?benchmarkNumber(row.reference_gbps):'<span title="Unavailable">—</span>'}${row.source_url?`<small class="block">${referenceSourceLink(row.source_url,'Source ↗')}</small>`:''}</td><td>${row.observed_gbps!=null?benchmarkNumber(row.observed_gbps):'<span title="Not measured">—</span>'}</td><td class="${delta!=null&&delta<0?'delta-worse':delta!=null?'delta-better':''}">${ncclDeltaText(row)}</td></tr>`;}).join('')}</tbody></table></div>${summary.context_note?`<p class="form-note">${esc(summary.context_note)}</p>`:''}<div class="nccl-improvements"><h4>Ways to improve</h4><ol type="a">${improvements.map(option=>`<li><strong>${esc(option.title||'Follow-up test')}</strong>${option.detail?` — ${esc(option.detail)}`:''}</li>`).join('')}</ol></div></section>`;}
function renderNcclComparison(result,name){return `<article class="card comparison-summary"><h2>${esc(name||result.run?.title||'NCCL result')}</h2>${renderNcclSimpleAssessment(performanceOf(result),result.run)}</article>`;}
